<script>
(()=>{let items=<?php echo json_encode(array_values($clItems),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;const canEdit=<?php echo $clCanEdit?'true':'false'; ?>,rows=document.getElementById('clRows'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const functions={modbus_tcp:[['read_holding_tcp','read_holding_tcp'],['read_input_tcp','read_input_tcp'],['write_single_tcp','write_single_tcp'],['write_coil_tcp','write_coil_tcp']],modbus_rtu:[['read_holding_rtu','read_holding_rtu'],['read_input_rtu','read_input_rtu'],['recv_holding_rtu','recv_holding_rtu'],['write_single_rtu','write_single_rtu'],['write_coil_rtu','write_coil_rtu']],bacnet:[['analogInput','analogInput · Read'],['analogOutput','analogOutput · Read / Write'],['analogValue','analogValue · Read / Write'],['binaryInput','binaryInput · Read'],['binaryOutput','binaryOutput · Read / Write'],['binaryValue','binaryValue · Read / Write'],['multiStateInput','multiStateInput · Read'],['multiStateOutput','multiStateOutput · Read / Write'],['multiStateValue','multiStateValue · Read / Write']]};
function render(){rows.innerHTML=items.map((x,i)=>'<tr><td>'+(x.ID||i+1)+'</td><td><code>'+esc(x.cmdid||x.Command)+'</code></td><td>'+esc(x.Name)+'</td><td><span class="cl-protocol">'+esc(String(x.Protocol||'').replace('_',' ').toUpperCase())+'</span></td><td>'+esc(x.Function)+'</td><td>'+esc(x.Target)+'</td><td>'+((x.Min!==''&&x.Min!=null)||(x.Max!==''&&x.Max!=null)?esc(x.Min??'—')+' – '+esc(x.Max??'—'):'—')+' '+esc(x.Unit||'')+'</td><td><span class="cl-mode '+(x.ScheduleEnabled===true?'auto':'manual')+(x.Enabled===false?' is-disabled':'')+'" title="'+(x.Enabled===false?'Command disabled':(x.ScheduleEnabled===true?'Runs automatically by schedule':'Runs only when manually triggered'))+'"><i class="fa-solid '+(x.ScheduleEnabled===true?'fa-clock-rotate-left':'fa-hand-pointer')+'"></i> '+(x.ScheduleEnabled===true?'Auto':'Manual')+(x.Enabled===false?'<small>Disabled</small>':'')+'</span></td><td class="cl-actions">'+(canEdit?'<button data-action="run" data-index="'+i+'" title="Run local test"><i class="fa-solid fa-play"></i></button><button data-action="edit" data-index="'+i+'" title="Edit"><i class="fa-solid fa-pen"></i></button><button data-action="remove" data-index="'+i+'" title="Remove"><i class="fa-solid fa-trash"></i></button>':'—')+'</td></tr>').join('')||'<tr><td colspan="9" class="cl-empty">No special commands configured</td></tr>';document.getElementById('clCount').textContent=items.length+' Commands';}render();
document.querySelectorAll('.cl-time24').forEach(input=>input.addEventListener('input',()=>{const digits=input.value.replace(/\D/g,'').slice(0,6);input.value=digits.length>4?digits.slice(0,2)+':'+digits.slice(2,4)+':'+digits.slice(4):digits.length>2?digits.slice(0,2)+':'+digits.slice(2):digits;}));
if(window.jQuery&&jQuery.fn.datetimepicker){jQuery('.cl-time24').datetimepicker({datepicker:false,timepicker:true,format:'H:i:s',formatTime:'H:i:s',step:1,hours12:false,closeOnTimeSelect:true,scrollInput:false});}
<?php if($clCanEdit): ?>const modal=document.getElementById('clModal'),form=document.getElementById('clForm'),protocol=document.getElementById('clProtocol'),fn=document.getElementById('clFunction'),key=document.getElementById('clKey'),error=document.getElementById('clError');let editIndex=-1;
const fields={Name:'clName',IpAddress:'clIpAddress',Port:'clPort',UnitId:'clUnitId',SerialPort:'clSerialPort',BaudRate:'clBaudRate',Parity:'clParity',StopBits:'clStopBits',SlaveId:'clSlaveId',BacnetIp:'clBacnetIp',BacnetPort:'clBacnetPort',DeviceInstance:'clDeviceInstance',Target:'clTarget',Value:'clValue',DataType:'clDataType',Min:'clMin',Max:'clMax',Unit:'clUnit',Description:'clDescription',ScheduleMode:'clScheduleMode',ScheduleDate:'clScheduleDate',ScheduleTime:'clScheduleTime',DurationValue:'clDurationValue',DurationUnit:'clDurationUnit',RepeatValue:'clRepeatValue',RepeatUnit:'clRepeatUnit'};
const makeCmdId=()=>{let id;do{id='C'+String(Date.now())+String(Math.floor(performance.now()*10)%10);}while(items.some(x=>(x.cmdid||x.Command)===id));return id;};async function loadSerialPorts(){const select=document.getElementById('clSerialPort'),button=document.getElementById('clRefreshPorts'),current=select.value;button.disabled=true;select.innerHTML='<option value="">Scanning available ports...</option>';try{const response=await fetch('./mx_fn_api.php?action=serial_ports',{cache:'no-store'}),ports=await response.json();if(!response.ok)throw Error('Scan failed');select.innerHTML=ports.length?'<option value="">Select serial port...</option>'+ports.map(p=>'<option value="'+esc(p.path)+'"'+(p.path===current||p.device===current?' selected':'')+'>'+esc(p.path)+' · Available</option>').join(''):'<option value="">No serial ports found</option>';}catch(e){select.innerHTML='<option value="">Unable to scan serial ports</option>';}finally{button.disabled=false;}}function updateSchedule(){const enabled=document.getElementById('clScheduleEnabled').checked,mode=document.getElementById('clScheduleMode').value,box=document.querySelector('.cl-schedule');box.classList.toggle('schedule-off',!enabled);document.getElementById('clScheduleDateField').hidden=mode!=='once';document.getElementById('clWeekDays').hidden=mode!=='weekly';}function setFunctions(selected=''){fn.innerHTML=functions[protocol.value].map(x=>'<option value="'+x[0]+'"'+(x[0]===selected?' selected':'')+'>'+x[1]+'</option>').join('');document.getElementById('clTargetLabel').textContent=protocol.value==='bacnet'?'BACnet object / property':'Register address';const tcp=protocol.value==='modbus_tcp',rtu=protocol.value==='modbus_rtu',bacnet=protocol.value==='bacnet';['clIpField','clPortField','clUnitField'].forEach(id=>document.getElementById(id).hidden=!tcp);['clSerialField','clBaudField','clParityField','clStopBitsField','clSlaveField'].forEach(id=>document.getElementById(id).hidden=!rtu);['clBacnetIpField','clBacnetPortField','clDeviceInstanceField'].forEach(id=>document.getElementById(id).hidden=!bacnet);document.getElementById('clIpAddress').required=tcp;document.getElementById('clPort').required=tcp;document.getElementById('clSerialPort').required=rtu;document.getElementById('clSlaveId').required=rtu;document.getElementById('clBacnetIp').required=bacnet;document.getElementById('clBacnetPort').required=bacnet;document.getElementById('clDeviceInstance').required=bacnet;if(rtu)loadSerialPorts();}protocol.onchange=()=>setFunctions();document.getElementById('clScheduleEnabled').onchange=updateSchedule;document.getElementById('clScheduleMode').onchange=updateSchedule;document.getElementById('clRefreshPorts').onclick=loadSerialPorts;const close=()=>{modal.hidden=true;error.textContent='';};function open(index=-1){editIndex=index;form.reset();document.getElementById('clEnabled').checked=true;const x=index>=0?items[index]:null;document.getElementById('clModalTitle').textContent=x?'Edit Command':'Add Command';if(x){key.value=x.cmdid||x.Command||'';protocol.value=x.Protocol||'modbus_tcp';setFunctions(x.Function||'');Object.entries(fields).forEach(([k,id])=>document.getElementById(id).value=x[k]??'');document.getElementById('clEnabled').checked=x.Enabled!==false;document.getElementById('clScheduleEnabled').checked=x.ScheduleEnabled===true;document.querySelectorAll('#clWeekDays input').forEach(c=>c.checked=(x.WeekDays||[]).map(String).includes(c.value));updateSchedule();}else{key.value=makeCmdId();protocol.value='modbus_tcp';document.getElementById('clPort').value='502';document.getElementById('clUnitId').value='1';document.getElementById('clBaudRate').value='115200';document.getElementById('clSlaveId').value='1';document.getElementById('clBacnetPort').value='47808';document.getElementById('clScheduleEnabled').checked=false;document.getElementById('clScheduleTime').value='00:00:00';document.getElementById('clDurationValue').value='60';document.getElementById('clRepeatValue').value='1';setFunctions();updateSchedule();}document.getElementById('clCmdHeader').textContent=key.value;modal.hidden=false;document.getElementById('clName').focus();}document.getElementById('clAdd').onclick=()=>open();document.getElementById('clClose').onclick=close;document.getElementById('clCancel').onclick=close;modal.onclick=e=>{if(e.target===modal)close();};async function save(){const response=await fetch('./mx_fn_api.php?action=command_list_save',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'dataE='+encodeURIComponent(JSON.stringify(items))});const data=await response.json();if(!response.ok||data.error)throw Error(data.error||'Save failed');items=data;render();close();}form.onsubmit=async e=>{e.preventDefault();const cmdid=key.value.trim(),min=document.getElementById('clMin').value,max=document.getElementById('clMax').value,ip=document.getElementById('clIpAddress').value.trim(),port=document.getElementById('clPort').value;if(min!==''&&max!==''&&Number(min)>Number(max)){error.textContent='Minimum must not exceed Maximum';return;}if(protocol.value==='modbus_tcp'&&!/^(?:\d{1,3}\.){3}\d{1,3}$/.test(ip)){error.textContent='Please enter a valid IP Address';return;}const x={ID:editIndex>=0?(items[editIndex].ID||editIndex+1):items.length+1,cmdid:cmdid,Name:document.getElementById('clName').value.trim(),Protocol:protocol.value,Function:fn.value,IpAddress:protocol.value==='modbus_tcp'?ip:'',Port:protocol.value==='modbus_tcp'?Number(port):'',UnitId:protocol.value==='modbus_tcp'?Number(document.getElementById('clUnitId').value):'',SerialPort:protocol.value==='modbus_rtu'?document.getElementById('clSerialPort').value.trim():'',BaudRate:protocol.value==='modbus_rtu'?Number(document.getElementById('clBaudRate').value):'',Parity:protocol.value==='modbus_rtu'?document.getElementById('clParity').value:'',StopBits:protocol.value==='modbus_rtu'?Number(document.getElementById('clStopBits').value):'',SlaveId:protocol.value==='modbus_rtu'?Number(document.getElementById('clSlaveId').value):'',BacnetIp:protocol.value==='bacnet'?document.getElementById('clBacnetIp').value.trim():'',BacnetPort:protocol.value==='bacnet'?Number(document.getElementById('clBacnetPort').value):'',DeviceInstance:protocol.value==='bacnet'?Number(document.getElementById('clDeviceInstance').value):'',
Target:document.getElementById('clTarget').value.trim(),
Value:document.getElementById('clValueField').hidden||document.getElementById('clValue').value===''?'':Number(document.getElementById('clValue').value),
DataType:document.getElementById('clDataType').value,Min:min===''?'':Number(min),Max:max===''?'':Number(max),Unit:document.getElementById('clUnit').value.trim(),Description:document.getElementById('clDescription').value.trim(),ScheduleEnabled:document.getElementById('clScheduleEnabled').checked,ScheduleMode:document.getElementById('clScheduleMode').value,ScheduleDate:document.getElementById('clScheduleDate').value,ScheduleTime:document.getElementById('clScheduleTime').value,DurationValue:Number(document.getElementById('clDurationValue').value),DurationUnit:document.getElementById('clDurationUnit').value,RepeatValue:Number(document.getElementById('clRepeatValue').value),RepeatUnit:document.getElementById('clRepeatUnit').value,WeekDays:[...document.querySelectorAll('#clWeekDays input:checked')].map(c=>Number(c.value)),Enabled:document.getElementById('clEnabled').checked};
if(!x.Name||!x.Target){error.textContent='Name and Target are required';return;}if(editIndex>=0)items[editIndex]=x;else items.push(x);try{document.getElementById('clSubmit').disabled=true;await save();}catch(err){error.textContent=err.message;}finally{document.getElementById('clSubmit').disabled=false;}};
rows.onclick=async e=>{const b=e.target.closest('button[data-action]');if(!b)return;const i=Number(b.dataset.index),item=items[i];if(b.dataset.action==='run'){if(item.Enabled===false){if(window.Swal)Swal.fire('ไม่สามารถทดสอบได้','Command นี้ถูกปิดใช้งาน','warning');else alert('This command is disabled');return;}let confirmed=true;if(window.Swal){const answer=await Swal.fire({title:'Run Local Test?',html:'<div class="cl-test-confirm"><b>'+esc(item.Name)+'</b><span>'+esc(item.Protocol)+' · '+esc(item.Function)+'</span><small>คำสั่งจะถูกส่งไปยังอุปกรณ์จริง แต่ไม่ส่ง status/reply ไป Server</small></div>',icon:'question',showCancelButton:true,confirmButtonText:'<i class="fa-solid fa-play"></i> เริ่มทดสอบ',cancelButtonText:'ยกเลิก',confirmButtonColor:'#087fbd'});confirmed=answer.isConfirmed;}else confirmed=confirm('Run '+item.Name+' on the configured device now?');if(!confirmed)return;b.disabled=true;try{if(window.Swal)Swal.fire({title:'กำลังทดสอบคำสั่ง',html:'<div class="cl-test-running"><i class="fa-solid fa-terminal"></i><b>'+esc(item.Name)+'</b><span>กำลังรอ Feedback จาก py_multi.py...</span></div>',allowOutsideClick:false,showConfirmButton:false,didOpen:()=>Swal.showLoading()});const response=await fetch('./mx_fn_api.php?action=command_manual_run',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'cmdid='+encodeURIComponent(item.cmdid||item.Command)}),queued=await response.json();if(!response.ok||queued.error)throw Error(queued.error||'Unable to queue command');let result=null;for(let attempt=0;attempt<32;attempt++){await new Promise(resolve=>setTimeout(resolve,500));const statusResponse=await fetch('./mx_fn_api.php?action=command_manual_result&run_id='+encodeURIComponent(queued.run_id),{cache:'no-store'}),status=await statusResponse.json();if(!statusResponse.ok||status.error)throw Error(status.error||'Unable to read feedback');if(!status.pending){result=status;break;}}if(!result)throw Error('ไม่ได้รับ Feedback ภายใน 16 วินาที');if(result.success){const feedback=result.feedback||{},detail=Object.entries(feedback).map(([key,value])=>'<div><span>'+esc(key)+'</span><b>'+esc(Array.isArray(value)?value.join(', '):value)+'</b></div>').join('');if(window.Swal)Swal.fire({icon:'success',title:'ทดสอบสำเร็จ',html:'<div class="cl-test-result"><strong>'+esc(result.name||item.Name)+'</strong>'+detail+'<small>'+esc(result.finished_at||'')+'</small></div>',confirmButtonText:'ปิด',confirmButtonColor:'#168c68'});else alert('Command completed successfully');}else throw Error(result.error||'Command failed');}catch(err){if(window.Swal)Swal.fire({icon:'error',title:'ทดสอบไม่สำเร็จ',html:'<div class="cl-test-error"><b>'+esc(item.Name)+'</b><span>'+esc(err.message)+'</span><small>ตรวจสอบ IP, Port, Address, Function และสิทธิ์การเขียนของอุปกรณ์</small></div>',confirmButtonText:'ปิด'});else alert(err.message);}finally{b.disabled=false;}return;}if(b.dataset.action==='edit'){open(i);return;}if(confirm('Remove '+(item.cmdid||item.Command)+'?')){items.splice(i,1);save().catch(err=>alert(err.message));}};<?php endif; ?>})();
</script>
<script>
(()=>{const modal=document.getElementById('clModal'),time=document.getElementById('clScheduleTime');if(!modal||!time)return;const normalize=()=>{if(!modal.hidden&&/^\d{2}:\d{2}$/.test(time.value))time.value+=':00';};new MutationObserver(normalize).observe(modal,{attributes:true,attributeFilter:['hidden']});time.addEventListener('blur',normalize);})();
</script>
<script>
(()=>{const modal=document.getElementById('clModal'),protocol=document.getElementById('clProtocol'),fn=document.getElementById('clFunction'),field=document.getElementById('clValueField'),value=document.getElementById('clValue');if(!modal||!protocol||!fn||!field)return;const sync=()=>{const name=fn.value||'',bacnet=protocol.value==='bacnet',writable=bacnet?!/Input$/.test(name):name.indexOf('write_')===0;field.hidden=!writable;value.required=writable;document.querySelector('.cl-command').classList.toggle('is-read',!writable);};fn.addEventListener('change',sync);protocol.addEventListener('change',()=>setTimeout(sync,0));new MutationObserver(sync).observe(modal,{attributes:true,attributeFilter:['hidden']});sync();})();
</script>
<script>
(()=>{const value=document.getElementById('clDurationValue'),unit=document.getElementById('clDurationUnit');if(!value||!unit)return;const help=value.closest('label').querySelector('.cl-help');const limits={seconds:60,minutes:60,hours:24};const labels={seconds:'วินาที',minutes:'นาที',hours:'ชั่วโมง'};const validate=show=>{const max=limits[unit.value]||60,n=Number(value.value);value.min='0';value.max=String(max);const invalid=value.value!==''&&(!Number.isFinite(n)||n<0||n>max);value.setCustomValidity(invalid?'Run duration ต้องอยู่ระหว่าง 0–'+max+' '+labels[unit.value]:'');if(help)help.textContent='กรอกได้ 0–'+max+' '+labels[unit.value];if(show&&invalid)value.reportValidity();};unit.addEventListener('change',()=>validate(true));value.addEventListener('input',()=>validate(false));value.addEventListener('change',()=>validate(true));new MutationObserver(()=>validate(false)).observe(document.getElementById('clModal'),{attributes:true,attributeFilter:['hidden']});validate(false);})();
</script>
<script>
(()=>{const input=document.getElementById('clScheduleTime'),modal=document.getElementById('clModal');if(!input||!modal)return;if(window.jQuery&&jQuery.fn.datetimepicker)jQuery(input).datetimepicker('destroy');const editor=document.createElement('div');editor.className='cl-clock-editor';input.parentNode.insertBefore(editor,input);editor.appendChild(input);const button=document.createElement('button');button.type='button';button.className='cl-clock-button';button.title='เลือกเวลา';button.innerHTML='<i class="fa-solid fa-clock"></i>';editor.appendChild(button);const picker=document.createElement('div');picker.className='cl-clock-picker';picker.hidden=true;picker.innerHTML='<div class="cl-clock-title"><b><i class="fa-solid fa-clock"></i><span>เลือกเวลาแบบ 24 ชั่วโมง</span></b><button type="button" aria-label="Close">&times;</button></div><div class="cl-clock-labels"><span><i class="fa-solid fa-clock"></i> ชั่วโมง</span><span><i class="fa-solid fa-hourglass-half"></i> นาที</span><span><i class="fa-solid fa-stopwatch"></i> วินาที</span></div><div class="cl-clock-wheels"></div><button class="cl-clock-done" type="button"><i class="fa-solid fa-circle-check"></i><span>ใช้เวลานี้</span></button>';editor.appendChild(picker);const wheels=picker.querySelector('.cl-clock-wheels');const make=(name,max)=>{const select=document.createElement('select');select.size=5;select.setAttribute('aria-label',name);for(let n=0;n<=max;n++){const option=document.createElement('option');option.value=String(n).padStart(2,'0');option.textContent=option.value;select.appendChild(option);}return select;};const hour=make('Hour',23),minute=make('Minute',59),second=make('Second',59);wheels.append(hour,minute,second);const fromInput=()=>{const match=String(input.value||'00:00:00').match(/^(\d{2}):(\d{2})(?::(\d{2}))?/);hour.value=match?match[1]:'00';minute.value=match?match[2]:'00';second.value=match&&match[3]?match[3]:'00';};const toInput=()=>{input.value=hour.value+':'+minute.value+':'+second.value;input.dispatchEvent(new Event('change',{bubbles:true}));};button.addEventListener('click',()=>{fromInput();picker.hidden=!picker.hidden;if(!picker.hidden)hour.focus();});[hour,minute,second].forEach(select=>select.addEventListener('change',toInput));picker.querySelector('.cl-clock-done').addEventListener('click',()=>{toInput();picker.hidden=true;input.focus();});picker.querySelector('.cl-clock-title button').addEventListener('click',()=>picker.hidden=true);document.addEventListener('pointerdown',event=>{if(!editor.contains(event.target))picker.hidden=true;});new MutationObserver(()=>{if(!modal.hidden){setTimeout(fromInput,0);}else picker.hidden=true;}).observe(modal,{attributes:true,attributeFilter:['hidden']});fromInput();})();
</script>
<script>
(()=>{const days=document.getElementById('clWeekDays');if(!days)return;const title=days.querySelector(':scope>span');if(title)title.textContent='เลือกวันที่ต้องการให้ทำงาน';const help=document.createElement('small');help.className='cl-weekdays-help';help.textContent='เลือกวันในสัปดาห์ที่ต้องการให้ระบบส่งคำสั่งนี้ สามารถเลือกได้มากกว่า 1 วัน';days.insertBefore(help,title?title.nextSibling:days.firstChild);})();
