<script>
(()=>{const title=document.getElementById('clModalTitle');if(!title)return;const ensure=()=>{if(title.querySelector('.fa-terminal'))return;const text=title.textContent;title.textContent='';const icon=document.createElement('i');icon.className='fa-solid fa-terminal';const label=document.createElement('span');label.textContent=text;title.append(icon,label);};new MutationObserver(ensure).observe(title,{childList:true});ensure();})();
