<script>
(()=>{const input=document.getElementById('clScheduleDate'),field=document.getElementById('clScheduleDateField'),modal=document.getElementById('clModal');if(!input||!field||!modal)return;if(window.jQuery&&jQuery.fn.datetimepicker)jQuery(input).datetimepicker('destroy');const title=field.querySelector(':scope>span');if(title)title.textContent='Start date (YYYY-MM-DD)';input.type='text';input.placeholder='YYYY-MM-DD';input.inputMode='numeric';input.maxLength=10;input.pattern='\\d{4}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12]\\d|3[01])';const editor=document.createElement('div');editor.className='cl-date-editor';input.parentNode.insertBefore(editor,input);editor.appendChild(input);const trigger=document.createElement('button');trigger.type='button';trigger.className='cl-date-button';trigger.title='เลือกวันที่';trigger.innerHTML='<i class="fa-regular fa-calendar"></i>';editor.appendChild(trigger);const calendar=document.createElement('div');calendar.className='cl-date-calendar';calendar.hidden=true;calendar.innerHTML='<div class="cl-date-head"><button type="button" data-move="-1">&#8249;</button><strong></strong><button type="button" data-move="1">&#8250;</button></div><div class="cl-date-week"><span>อา.</span><span>จ.</span><span>อ.</span><span>พ.</span><span>พฤ.</span><span>ศ.</span><span>ส.</span></div><div class="cl-date-grid"></div><small><i class="fa-solid fa-circle-info"></i> คลิกวันที่เพื่อเลือกวันเริ่มทำงาน</small>';editor.appendChild(calendar);let month=new Date();const key=date=>date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');const selectedDate=()=>/^\d{4}-\d{2}-\d{2}$/.test(input.value)?new Date(input.value+'T00:00:00'):null;const render=()=>{const selected=selectedDate(),year=month.getFullYear(),m=month.getMonth(),first=new Date(year,m,1),start=new Date(year,m,1-first.getDay()),today=key(new Date());calendar.querySelector('strong').textContent=first.toLocaleDateString('th-TH',{month:'long',year:'numeric'});const grid=calendar.querySelector('.cl-date-grid');grid.innerHTML='';for(let i=0;i<42;i++){const date=new Date(start);date.setDate(start.getDate()+i);const button=document.createElement('button');button.type='button';button.textContent=date.getDate();button.dataset.date=key(date);if(date.getMonth()!==m)button.classList.add('outside');if(button.dataset.date===today)button.classList.add('today');if(selected&&button.dataset.date===key(selected))button.classList.add('selected');grid.appendChild(button);}};const syncMonth=()=>{const selected=selectedDate();if(selected&&!Number.isNaN(selected.getTime()))month=new Date(selected.getFullYear(),selected.getMonth(),1);render();};trigger.addEventListener('click',()=>{syncMonth();calendar.hidden=!calendar.hidden;});calendar.addEventListener('click',event=>{const move=event.target.closest('[data-move]');if(move){month.setMonth(month.getMonth()+Number(move.dataset.move));render();return;}const day=event.target.closest('[data-date]');if(day){input.value=day.dataset.date;input.dispatchEvent(new Event('change',{bubbles:true}));calendar.hidden=true;render();}});input.addEventListener('input',()=>{const digits=input.value.replace(/\D/g,'').slice(0,8);input.value=digits.length>6?digits.slice(0,4)+'-'+digits.slice(4,6)+'-'+digits.slice(6):digits.length>4?digits.slice(0,4)+'-'+digits.slice(4):digits;});input.addEventListener('change',syncMonth);document.addEventListener('pointerdown',event=>{if(!editor.contains(event.target))calendar.hidden=true;});new MutationObserver(()=>{if(!modal.hidden)setTimeout(syncMonth,0);else calendar.hidden=true;}).observe(modal,{attributes:true,attributeFilter:['hidden']});syncMonth();})();
</script>
<script>
(()=>{const calendar=document.querySelector('.cl-date-calendar'),input=document.getElementById('clScheduleDate');if(!calendar||!input)return;const head=calendar.querySelector('.cl-date-head'),label=head.querySelector('strong'),prev=head.querySelector('[data-move="-1"]'),next=head.querySelector('[data-move="1"]');label.hidden=true;const controls=document.createElement('div');controls.className='cl-date-jump';const monthSelect=document.createElement('select'),yearSelect=document.createElement('select');['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'].forEach((name,index)=>monthSelect.add(new Option(name,String(index))));const baseYear=new Date().getFullYear();for(let year=baseYear-15;year<=baseYear+15;year++)yearSelect.add(new Option(String(year),String(year)));controls.append(monthSelect,yearSelect);head.insertBefore(controls,next);let cursor=new Date(baseYear,new Date().getMonth(),1);const fromInput=()=>{const match=input.value.match(/^(\d{4})-(\d{2})/);cursor=match?new Date(Number(match[1]),Number(match[2])-1,1):new Date();monthSelect.value=String(cursor.getMonth());yearSelect.value=String(cursor.getFullYear());};const jump=()=>{const target=new Date(Number(yearSelect.value),Number(monthSelect.value),1),diff=(target.getFullYear()-cursor.getFullYear())*12+target.getMonth()-cursor.getMonth(),button=diff<0?prev:next;for(let i=0;i<Math.abs(diff);i++)button.click();cursor=target;};monthSelect.addEventListener('change',jump);yearSelect.addEventListener('change',jump);prev.addEventListener('click',()=>{cursor.setMonth(cursor.getMonth()-1);monthSelect.value=String(cursor.getMonth());yearSelect.value=String(cursor.getFullYear());});next.addEventListener('click',()=>{cursor.setMonth(cursor.getMonth()+1);monthSelect.value=String(cursor.getMonth());yearSelect.value=String(cursor.getFullYear());});document.querySelector('.cl-date-button').addEventListener('click',()=>setTimeout(fromInput,0));fromInput();})();
</script>
<script>
(()=>{const picker=document.querySelector('.cl-clock-picker'),input=document.getElementById('clScheduleTime');if(!picker||!input)return;const title=picker.querySelector('.cl-clock-title'),close=title.querySelector('button');const nowButton=document.createElement('button');nowButton.type='button';nowButton.className='cl-clock-now';nowButton.innerHTML='<i class="fa-solid fa-clock-rotate-left"></i> ตอนนี้';title.insertBefore(nowButton,close);nowButton.addEventListener('click',()=>{const now=new Date();input.value=[now.getHours(),now.getMinutes(),now.getSeconds()].map(value=>String(value).padStart(2,'0')).join(':');input.dispatchEvent(new Event('change',{bubbles:true}));const selects=picker.querySelectorAll('.cl-clock-wheels select');selects[0].value=String(now.getHours()).padStart(2,'0');selects[1].value=String(now.getMinutes()).padStart(2,'0');selects[2].value=String(now.getSeconds()).padStart(2,'0');});})();
</script>
